    public sealed class TexturePreview : Control {
        public Workspace Workspace; public TextureRegion TextureRegion; public string Error;public bool Crop=true;public ThemePalette Palette=ThemeCatalog.Create("classic");
        public TexturePreview(){DoubleBuffered=true;Height=180;Dock=DockStyle.Fill;}
        protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.Clear(Palette.Input);try{if(Workspace==null||TextureRegion==null||TextureRegion.FilePath==null){TextRenderer.DrawText(g,Error??"Выберите элемент с текстурой",Font,Rectangle.Inflate(ClientRectangle,-10,-10),Palette.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.WordBreak);return;}var b=Workspace.Image(TextureRegion.FilePath);RectangleF source=Crop?TextureRegion.Source:new RectangleF(0,0,b.Width,b.Height);if(source.Width<=0||source.Height<=0)return;float z=Math.Max(.001f,Math.Min((Width-24f)/source.Width,(Height-24f)/source.Height));var rect=new RectangleF((Width-source.Width*z)/2,(Height-source.Height*z)/2,source.Width*z,source.Height*z);using(var br=new SolidBrush(Palette.Panel))g.FillRectangle(br,rect);using(var br=new SolidBrush(Palette.Raised)){for(int y=(int)rect.Top;y<rect.Bottom;y+=12)for(int x=(int)rect.Left;x<rect.Right;x+=12)if(((x/12+y/12)&1)==0)g.FillRectangle(br,RectangleF.Intersect(rect,new RectangleF(x,y,12,12)));}g.InterpolationMode=z>=1?InterpolationMode.NearestNeighbor:InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.Half;g.DrawImage(b,rect,source,GraphicsUnit.Pixel);if(!Crop){var r=TextureRegion.Source;using(var pen=new Pen(Palette.Accent,2))g.DrawRectangle(pen,rect.Left+r.X*z,rect.Top+r.Y*z,r.Width*z,r.Height*z);}using(var pen=new Pen(Palette.Border))g.DrawRectangle(pen,rect.X,rect.Y,rect.Width,rect.Height);}catch(Exception ex){TextRenderer.DrawText(g,ex.Message,Font,Rectangle.Inflate(ClientRectangle,-8,-8),Palette.Accent,TextFormatFlags.WordBreak);}}
    }
