        void ShowError(string text){status.Text=text;MessageBox.Show(this,text,"X-Ray UI Editor",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
        void GridKey(object sender,KeyEventArgs e){if(e.KeyCode==Keys.Enter){GridStepChanged(sender,EventArgs.Empty);Canvas.Focus();e.Handled=true;}}
        void GridStepChanged(object sender,EventArgs e){int x,y;if(!int.TryParse(gridX.Text,out x)||x<1||x>1024||!int.TryParse(gridY.Text,out y)||y<1||y>1024){gridX.Text=Canvas.Options.GridX.ToString();gridY.Text=Canvas.Options.GridY.ToString();status.Text="Шаг сетки: целое число от 1 до 1024";return;}Canvas.Options.GridX=x;Canvas.Options.GridY=y;Canvas.Invalidate();}
        void SetMajorGrid(){string s=Prompt.Ask(this,"Основные линии","Каждая N-я линия (1–64):",Canvas.Options.Major.ToString());int v;if(s!=null&&int.TryParse(s,out v)&&v>=1&&v<=64){Canvas.Options.Major=v;Canvas.Invalidate();}}
        void ChooseColor(bool grid){using(var d=new ColorDialog{Color=grid?Canvas.Options.GridColor:Canvas.Options.BackgroundColor})if(d.ShowDialog(this)==DialogResult.OK){if(grid)Canvas.Options.GridColor=d.Color;else Canvas.Options.BackgroundColor=d.Color;Canvas.Invalidate();}}
        void OpenFolder(){using(var d=new FolderBrowserDialog{Description="Выберите папку с config(s), XML и textures. Для архива примеров — папку, где лежат config и textures."})if(d.ShowDialog(this)==DialogResult.OK)OpenWorkspace(d.SelectedPath,null);}
        void OpenXml(){using(var d=new OpenFileDialog{Filter="UI XML|*.xml|Все файлы|*.*"})if(d.ShowDialog(this)==DialogResult.OK){if(Workspace!=null&&d.FileName.StartsWith(Workspace.Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))OpenDocument(d.FileName);else OpenWorkspace(Workspace.FindRoot(d.FileName),d.FileName);}}
        public bool OpenWorkspace(string root,string file){return OpenWorkspace(root,file,false);}
        bool OpenWorkspace(string root,string file,bool leaveConfirmed){if(!leaveConfirmed&&!CanLeaveWorkspace())return false;UseWaitCursor=true;try{var next=new Workspace(root);if(Workspace!=null)Workspace.Dispose();Workspace=next;Document=null;Canvas.Bind(next,null);sourceDirty=false;sourceBase="";FillFiles();projectLabel.Text=Path.GetFileName(root)+"\n"+Workspace.Files.Count+" XML · "+Workspace.ImageFiles.Count+" текстур";tips.SetToolTip(projectLabel,root);if(file==null){foreach(string p in Workspace.Files)if(Path.GetFileName(p).Equals("inventory_new.xml",StringComparison.OrdinalIgnoreCase)){file=p;break;}}if(file==null&&Workspace.Files.Count>0)file=Workspace.Files[0];if(file!=null)OpenDocument(file);else{FillTextures();FillTree();ShowSelection();}status.Text="Проект открыт. Двойной щелчок по XML для выбора.";return true;}finally{UseWaitCursor=false;}}
        void OpenSelectedFile(){var f=files.SelectedItem as FileEntry;if(f!=null)OpenDocument(f.Path);}
        public void OpenDocument(string path){if(!EnsureSource())return;var next=Workspace.Open(path);Document=next;Workspace.Activate(next);Canvas.Bind(Workspace,next);binding=true;source.Text=Document.Text;sourceBase=Document.Text;sourceDirty=false;binding=false;aspect.SelectedIndex=Path.GetFileNameWithoutExtension(path).EndsWith("_16",StringComparison.OrdinalIgnoreCase)?1:0;RefreshDocument(true);leftTabs.SelectedIndex=1;centerTabs.SelectedIndex=Document.ParseError==null?0:1;Canvas.Focus();Canvas.Fit();if(Document.ParseError!=null){status.Text=Document.ParseError;MessageBox.Show(this,"XML открыт для исправления во вкладке кода.\n\n"+Document.ParseError,"Ошибка исходного XML",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
        void FillFiles(){if(Workspace==null)return;files.BeginUpdate();files.Items.Clear();string q=fileSearch.Text.Trim();foreach(var p in Workspace.Files){string label=p.Substring(Workspace.Root.Length).TrimStart(Path.DirectorySeparatorChar);if(q!=""&&label.IndexOf(q,StringComparison.OrdinalIgnoreCase)<0)continue;UiDocument d;bool dirty=Workspace.Documents.TryGetValue(p,out d)&&d.Dirty;files.Items.Add(new FileEntry{Path=p,Label=(dirty?"* ":"")+label});}files.EndUpdate();}
        void FillTextures(){textures.BeginUpdate();textures.Items.Clear();if(Workspace!=null){var ids=new List<string>(Workspace.Textures.Keys);ids.Sort(StringComparer.OrdinalIgnoreCase);foreach(string id in ids)if(id.IndexOf(textureSearch.Text.Trim(),StringComparison.OrdinalIgnoreCase)>=0)textures.Items.Add(id);}textures.EndUpdate();}
        void FillTree(){binding=true;tree.BeginUpdate();tree.Nodes.Clear();treeNodes.Clear();if(Document!=null){string q=nodeSearch.Text.Trim();TreeNode root=BuildTree(Document.Xml.Root,q);if(root!=null){tree.Nodes.Add(root);root.Expand();if(Document.Xml.Nodes.Count<90)root.ExpandAll();}if(Canvas.Primary!=null){TreeNode n;if(treeNodes.TryGetValue(Canvas.Primary.Key,out n)){tree.SelectedNode=n;n.EnsureVisible();}}}tree.EndUpdate();binding=false;}
        TreeNode BuildTree(UiNode n,string q){string tx=UiLayout.TextureName(Document,n);string label=n.Name=="texture"&&n.Has("id")?n.Get("id",n.Name):n.Name;var result=new TreeNode(label){Tag=n.Key,ToolTipText=n.Key+(tx==""?"":"\nТекстура: "+tx)};foreach(var c in n.Children){var child=BuildTree(c,q);if(child!=null)result.Nodes.Add(child);}bool hit=q==""||label.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0||tx.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0;if(!hit&&result.Nodes.Count==0)return null;if(Document.Hidden.Contains(n.Key))result.ForeColor=Color.Gray;else if(n.Name.StartsWith("dragdrop_"))result.ForeColor=Accent;else if(n.Geometry)result.ForeColor=Color.FromArgb(150,206,203);treeNodes[n.Key]=result;return result;}
        void RefreshDocument(bool full){if(Document==null)return;Canvas.Selection.RemoveAll(delegate(string key){return Document.Node(key)==null;});if(Document.Atlas){Workspace.Reindex();Canvas.AtlasFile=Canvas.Primary==null?Document.DefaultAtlasReference:Document.AtlasReference(Canvas.Primary);if(Canvas.AtlasFile=="")Canvas.AtlasFile=Document.DefaultAtlasReference;}if(!sourceDirty){binding=true;int pos=source.SelectionStart;source.Text=Document.Text;sourceBase=Document.Text;source.Select(Math.Min(pos,source.TextLength),0);binding=false;}if(full){FillFiles();FillTextures();}FillTree();FillPages();ShowSelection();Canvas.Invalidate();UpdateTitle();}
        void FillPages(){pages.DropDownItems.Clear();pages.Visible=Document!=null&&Document.Atlas;if(!pages.Visible)return;var refs=new HashSet<string>();foreach(var n in Document.Xml.Nodes){string name=Document.AtlasReference(n);if(name==""||!refs.Add(name))continue;string copy=name;var item=new ToolStripMenuItem(name){Checked=name==Canvas.AtlasFile};item.Click+=delegate{Canvas.AtlasFile=copy;Canvas.Selection.Clear();Canvas.Fit();FillPages();ShowSelection();};pages.DropDownItems.Add(item);}}
        void ShowSelection(){binding=true;var n=Canvas.Primary;properties.Rows.Clear();parentChoice.Items.Clear();preview.Workspace=Workspace;preview.TextureRegion=null;preview.Error=null;textureInfo.Text="";selectionLabel.Text=n==null?"СВОЙСТВА ЭЛЕМЕНТА":n.Get("id",n.Name);pathLabel.Text=n==null?"Выберите элемент на холсте или в дереве.":n.Key;textureName.Text=n==null?"":UiLayout.TextureName(Document,n);hidden.Checked=n!=null&&Document.Hidden.Contains(n.Key);locked.Checked=n!=null&&Document.Locked.Contains(n.Key);engine.Checked=Document==null||Document.EngineParents;
            if(n!=null){foreach(var a in n.Attributes)properties.Rows.Add(a.Name,a.Value);if(n.Geometry)foreach(string a in new[]{"x","y","width","height"})if(!n.Has(a))properties.Rows.Add(a,n.Get(a,"0"));TreeNode tn;if(treeNodes.TryGetValue(n.Key,out tn)){tree.SelectedNode=tn;tn.EnsureVisible();}parentChoice.Items.Add(new KeyEntry{Key="@auto",Label="Автоматически"});parentChoice.Items.Add(new KeyEntry{Key="@origin",Label="Начало экрана (0, 0)"});foreach(var candidate in Document.Xml.Nodes)if(candidate!=n&&candidate.Geometry&&!candidate.Key.StartsWith(n.Key+"/",StringComparison.Ordinal))parentChoice.Items.Add(new KeyEntry{Key=candidate.Key,Label=candidate.Key});string chosen;Document.PreviewParents.TryGetValue(n.Key,out chosen);parentChoice.SelectedIndex=0;for(int i=0;i<parentChoice.Items.Count;i++)if(((KeyEntry)parentChoice.Items[i]).Key==chosen)parentChoice.SelectedIndex=i;
                try{TextureRegion t;if(Document.Atlas)t=new TextureRegion{Id=n.Get("id",n.Name),FileReference=textureName.Text,FilePath=Workspace.ResolveFile(textureName.Text),Source=n.LocalRect,OwnerFile=Document.FilePath,NodeKey=n.Key};else t=Workspace.ResolveState(UiLayout.TextureName(Document,n,Canvas.Options.TextureState),Canvas.Options.TextureState);preview.TextureRegion=t;if(t!=null){textureInfo.Text=(t.FilePath==null?"Файл не найден: "+t.FileReference:Path.GetFileName(t.FilePath))+"\nUV: "+UiDocument.Num(t.Source.X)+", "+UiDocument.Num(t.Source.Y)+" · "+UiDocument.Num(t.Source.Width)+" × "+UiDocument.Num(t.Source.Height);tips.SetToolTip(textureInfo,(t.FilePath??t.FileReference)+"\n"+t.OwnerFile);}else if(textureName.Text!="")preview.Error="Текстура не найдена в выбранном варианте UI";}catch(Exception ex){preview.Error=ex.Message;}}
            selectedTextureLabel.Text=textureName.Text==""?"Текстура не назначена":"↗  "+textureName.Text;tips.SetToolTip(selectedTextureLabel,textureName.Text);UpdateCoordinates();UpdateGeometryInputs();binding=false;preview.Invalidate();}
        void UpdateCoordinates(){var n=Canvas.Primary;if(n==null){coordsLabel.Text="";return;}var r=UiLayout.Rect(Document,n);coordsLabel.Text="X "+n.Get("x","0")+"    Y "+n.Get("y","0")+"    W "+n.Get("width","0")+"    H "+n.Get("height","0")+"\nНа экране: "+UiDocument.Num(r.X)+", "+UiDocument.Num(r.Y)+(Canvas.Selection.Count>1?" · выделено "+Canvas.Selection.Count:"");}
        void UpdateTitle(){Text=(Document==null?"":(Document.Dirty||sourceDirty?"* ":"")+Path.GetFileName(Document.FilePath)+" — ")+"X-Ray UI Editor 1.1";UpdateWorkspaceHeading();documentStatus.Text=Document==null?"":(Document.Atlas?"АТЛАС":"РАЗВЁРСТКА")+" · "+Document.Encoding.WebName+" · "+(Workspace.ActiveVariant==""?"общий набор":Workspace.ActiveVariant)+(Document.Dirty||sourceDirty?" · изменён":"");}
        void Change(Action action){if(Document==null||!EnsureSource())return;string before=Document.Text;try{action();Document.Commit(before);RefreshDocument(false);}catch{if(Document.Text!=before)Document.SetText(before);throw;}}
        void PropertyChanged(object sender,DataGridViewCellEventArgs e){if(binding||e.RowIndex<0||e.ColumnIndex!=1||Canvas.Primary==null)return;string name=Convert.ToString(properties.Rows[e.RowIndex].Cells[0].Value),value=Convert.ToString(properties.Rows[e.RowIndex].Cells[1].Value),key=Canvas.Primary.Key;Guard(delegate{if(name=="x"||name=="y"||name=="width"||name=="height"||name=="cell_width"||name=="cell_height"){float f;if(!float.TryParse(value.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out f)||float.IsNaN(f)||float.IsInfinity(f))throw new FormatException("Нужно конечное число.");if(name!="x"&&name!="y"&&f<0)throw new FormatException("Размер не может быть отрицательным.");value=UiDocument.Num(f);}Change(delegate{Document.SetAttribute(key,name,value);});});ShowSelection();}
        void AddAttribute(){var n=Canvas.Primary;if(n==null)return;string name=Prompt.Ask(this,"Новый атрибут","Имя атрибута:","stretch");if(name==null)return;string value=Prompt.Ask(this,"Значение","Значение "+name+":","1");if(value!=null)Change(delegate{Document.SetAttribute(n.Key,name,value);});}
        void RemoveAttribute(){if(Canvas.Primary==null||properties.CurrentRow==null)return;string name=Convert.ToString(properties.CurrentRow.Cells[0].Value),key=Canvas.Primary.Key;Change(delegate{Document.RemoveAttribute(key,name);});}
        void ApplyTextureText(){var n=Canvas.Primary;if(n!=null){string name=textureName.Text.Trim();Change(delegate{Document.SetTexture(n.Key,name);});}}
        void ApplyTextureFromList(){if(textures.SelectedItem==null||Canvas.Primary==null||Document.Atlas){status.Text="Выберите элемент развёрстки, затем texture id.";return;}string name=textures.SelectedItem.ToString(),key=Canvas.Primary.Key;Change(delegate{Document.SetTexture(key,name);});}
        void JumpAtlas(){if(Document==null||Document.Atlas||Canvas.Primary==null)return;var t=Workspace.ResolveState(UiLayout.TextureName(Document,Canvas.Primary,Canvas.Options.TextureState),Canvas.Options.TextureState);if(t==null||t.OwnerFile==null){status.Text="У этой текстуры нет XML-дескриптора; её можно назначить своим фоном.";return;}OpenDocument(t.OwnerFile);Canvas.SelectKey(t.NodeKey,false);Canvas.Fit();}
        void SyncGrid(){var n=Canvas.Primary;if(n==null||!n.Has("cell_width")||!n.Has("cell_height")){status.Text="Выберите dragdrop с параметрами ячеек.";return;}Change(delegate{var v=new Dictionary<string,string>{{"width",UiDocument.Num(n.Number("cell_width",1)*n.Number("cols_num",1))},{"height",UiDocument.Num(n.Number("cell_height",1)*n.Number("rows_num",1))}};var d=new Dictionary<string,Dictionary<string,string>>();d[n.Key]=v;Document.SetAttributes(d);});}
        void TogglePreviewFlag(HashSet<string> set,bool enabled){if(binding||set==null||Canvas.Primary==null)return;foreach(string key in Canvas.Selection){if(enabled)set.Add(key);else set.Remove(key);}FillTree();Canvas.Invalidate();}
        void Undo(){if(centerTabs.SelectedIndex==1&&sourceDirty){source.Undo();return;}if(Document!=null&&Document.Undo())RefreshDocument(false);}
        void Redo(){if(centerTabs.SelectedIndex==1&&sourceDirty){source.Redo();return;}if(Document!=null&&Document.Redo())RefreshDocument(false);}
        void Duplicate(){var n=Canvas.Primary;if(n==null)return;string key=n.Key;Change(delegate{key=Document.Duplicate(key);});Canvas.SelectKey(key,false);}
        void Delete(){if(Document==null||Canvas.Selection.Count==0)return;var keys=new List<string>(Canvas.Selection);Change(delegate{Document.DeleteNodes(keys);});Canvas.Selection.Clear();RefreshDocument(false);}
        void AddNode(){if(Document==null)return;string name=Prompt.Ask(this,"Добавить элемент","Имя тега:",Document.Atlas?"texture":"auto_static");if(name==null)return;if(!System.Text.RegularExpressions.Regex.IsMatch(name,@"^[A-Za-z_][\w:.-]*$"))throw new FormatException("Некорректное имя тега.");var parent=Canvas.Primary??Document.Xml.Root;if(parent.SelfClosing||parent.Name=="texture")parent=parent.Parent??Document.Xml.Root;int pos=parent.CloseStart;string id=Document.Atlas?" id=\"new_texture_"+Guid.NewGuid().ToString("N").Substring(0,6)+"\"":"";string block="\n    <"+name+id+" x=\"0\" y=\"0\" width=\"64\" height=\"64\"/>\n";Change(delegate{Document.SetText(Document.Text.Insert(pos,block));});}
        bool ApplySource(){if(Document==null||!sourceDirty)return true;if(Document.Text!=sourceBase){ShowError("Развёрстка изменилась после начала правки XML. Скопируйте свой текст, затем отмените его правку и объедините изменения вручную.");return false;}string old=Document.Text;try{Document.SetText(source.Text);Document.Bytes();Document.Commit(old);sourceBase=Document.Text;sourceDirty=false;Workspace.Reindex();RefreshDocument(true);return true;}catch(Exception ex){if(Document.Text!=old)Document.SetText(old);ShowError(ex.Message);return false;}}
        bool EnsureSource(){if(!sourceDirty)return true;var r=MessageBox.Show(this,"Во вкладке XML есть неприменённые изменения. Применить их?\n«Нет» — вернуть текст текущей развёрстки.","Изменения XML",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(r==DialogResult.Cancel)return false;if(r==DialogResult.Yes)return ApplySource();binding=true;source.Text=Document.Text;sourceBase=Document.Text;sourceDirty=false;binding=false;return true;}
        void ShowInSource(){if(Canvas.Primary==null||!EnsureSource())return;centerTabs.SelectedIndex=1;source.Focus();source.Select(Canvas.Primary.Start,Canvas.Primary.OpenEnd-Canvas.Primary.Start);source.ScrollToCaret();}
        bool Save(bool saveAs){if(Document==null||!EnsureSource())return false;string path=Document.FilePath;if(saveAs){using(var d=new SaveFileDialog{Filter="UI XML|*.xml",FileName=Path.GetFileName(path),InitialDirectory=Path.GetDirectoryName(path)}){if(d.ShowDialog(this)!=DialogResult.OK)return false;path=d.FileName;}}string oldPath=Document.FilePath;string backup=Document.Save(path);if(!string.Equals(oldPath,path,StringComparison.OrdinalIgnoreCase)){Workspace.Documents.Remove(oldPath);Workspace.Documents[path]=Document;if(!Workspace.Files.Contains(path))Workspace.Files.Add(path);Workspace.Activate(Document);}RefreshDocument(true);status.Text=backup==""?"Сохранено: "+Path.GetFileName(path):"Сохранено. Резервная копия: "+Path.GetFileName(backup);return true;}
        void SaveAll(){if(Workspace==null||!EnsureSource())return;int count=0;foreach(var d in Workspace.Documents.Values)if(d.Dirty){d.Save(d.FilePath);count++;}RefreshDocument(true);status.Text="Сохранено XML: "+count;}
        bool CanLeaveWorkspace(){if(!EnsureSource())return false;if(Workspace==null)return true;int count=0;foreach(var d in Workspace.Documents.Values)if(d.Dirty)count++;if(count==0)return true;var r=MessageBox.Show(this,"Сохранить изменённые XML ("+count+")?","Закрытие проекта",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(r==DialogResult.Cancel)return false;if(r==DialogResult.Yes){try{SaveAll();}catch(Exception ex){ShowError(ex.Message);return false;}}return true;}
        void NewDocument(){using(var d=new SaveFileDialog{Filter="UI XML|*.xml",FileName="new_ui.xml"}){if(d.ShowDialog(this)!=DialogResult.OK)return;if(!CanLeaveWorkspace())return;string text="<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<window>\n    <main x=\"0\" y=\"0\" width=\"1024\" height=\"768\"/>\n    <auto_static x=\"64\" y=\"64\" width=\"256\" height=\"128\"/>\n</window>\n";if(File.Exists(d.FileName))throw new IOException("Для нового XML выберите несуществующее имя, чтобы сохранить существующий файл.");File.WriteAllText(d.FileName,text,new UTF8Encoding(false));OpenWorkspace(Workspace.FindRoot(d.FileName),d.FileName,true);}}
        void ChooseBackground(){using(var d=new OpenFileDialog{Filter="Текстуры|*.dds;*.png;*.bmp;*.jpg;*.jpeg"})if(d.ShowDialog(this)==DialogResult.OK){if(Workspace==null)OpenWorkspace(Path.GetDirectoryName(d.FileName),null);if(Workspace==null)return;Workspace.Image(d.FileName);Canvas.Options.ManualBackground=d.FileName;Canvas.Options.Background=true;toggles["background"].Checked=true;Canvas.Invalidate();}}
        void ChooseTexturesFolder(){if(Workspace==null)return;using(var d=new FolderBrowserDialog{Description="Папка textures или папка с DDS текущего варианта"})if(d.ShowDialog(this)==DialogResult.OK){Workspace.TextureDirectory=d.SelectedPath;Workspace.Reindex();FillTextures();ShowSelection();Canvas.Invalidate();}}
        void ExportImage(){if(Document==null)return;using(var d=new SaveFileDialog{Filter="PNG|*.png",FileName=Path.GetFileNameWithoutExtension(Document.FilePath)+"_preview.png"})if(d.ShowDialog(this)==DialogResult.OK){Canvas.Export(d.FileName);status.Text="Просмотр экспортирован в PNG.";}}
        void ValidateDocument(){if(Document==null||!EnsureSource())return;UseWaitCursor=true;try{var warnings=UiLayout.Validate(Document,Workspace);warnings.AddRange(Workspace.Warnings);ShowReport("Проверка XML",warnings.Count==0?"Проверка завершена: ошибок координат и подключений не найдено.":string.Join(Environment.NewLine,warnings.ToArray()));}finally{UseWaitCursor=false;}}
        void ShowReport(string title,string text){using(var f=new Form{Text=title,Size=new Size(820,540),StartPosition=FormStartPosition.CenterParent,Font=Font}){var t=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Text=text,BackColor=InputColor,ForeColor=TextColor};f.Controls.Add(t);ThemeCatalog.Apply(f,currentTheme);f.ShowDialog(this);}}
        void ShowHelp(){ShowReport("Управление", "Откройте папку, содержащую config(s) и textures. Архив сначала распакуйте.\r\nСлева: файлы, дерево элементов и список texture id. Двойной щелчок открывает XML.\r\n\r\nКолесо — масштаб под указателем. Средняя кнопка или пробел + мышь — панорама.\r\nПеретаскивание — позиция. Белые маркеры — размер. Ctrl + клик — несколько элементов.\r\nСтрелки — 1 единица, Shift + стрелки — 10. Alt во время перетаскивания отключает привязку.\r\nF — вписать выделение. Esc — отменить текущее перетаскивание.\r\nCtrl+S — сохранить; Ctrl+Z / Ctrl+Y — история; Ctrl+D — дубликат.\r\n\r\nСетка, привязка, имена, текстуры, рамки, ячейки и линейки включаются независимо.\r\n«Рамкой» — групповое выделение. F5 перечитывает DDS; F11 скрывает боковые панели.\r\nСемь тем — в меню «Тема» справа. Выбранная тема запоминается.\r\nКоординаты XML остаются в системе 1024×768. Режим 16:9 меняет только пропорции просмотра.\r\n\r\nВ режиме АТЛАС правятся UV-области texture id, в режиме РАЗВЁРСТКА — координаты окон.\r\nФайлы DDS не перезаписываются. Их цвет и пиксели здесь не редактируются.\r\nОригинальные комментарии, #include и кодировка XML сохраняются. При записи создаётся .bak.\r\n\r\nПросмотр не запускает движок игры: скрипты, динамический текст и анимация не исполняются;\r\n#include сохраняется как текст и не раскрывается. Шрифты INI/SEQ можно подключать в игре,\r\nно редактор не редактирует их. Составные рамки движка и разные состояния кнопок\r\nмогут выглядеть иначе; используется обычная текстура / состояние _e.\r\nДля нестандартного UI задайте родителя просмотра вручную.\r\nНастройки проекта (.halk.xml) сохраняют родителей, скрытие и блокировку отдельно от игровых XML.\r\n\r\nПоддержаны DDS DXT1/3/5, A8, RGB16/24/32, DX10 BC1/2/3 и RGBA/BGRA8.\r\nДля запуска используется системный .NET Framework. В программе нет сетевых запросов.");}
        void OnDragEnter(object sender,DragEventArgs e){e.Effect=e.Data.GetDataPresent(DataFormats.FileDrop)?DragDropEffects.Copy:DragDropEffects.None;}
        void OnDragDrop(object sender,DragEventArgs e){string[] items=e.Data.GetData(DataFormats.FileDrop) as string[];if(items==null||items.Length==0)return;Guard(delegate{string p=items[0];if(Directory.Exists(p))OpenWorkspace(p,null);else if(Path.GetExtension(p).Equals(".xml",StringComparison.OrdinalIgnoreCase))OpenWorkspace(Workspace.FindRoot(p),p);else status.Text="Перетащите распакованную папку проекта или XML.";});}
        void OnClosing(object sender,FormClosingEventArgs e){if(closingSmoke)return;if(!CanLeaveWorkspace()){e.Cancel=true;return;}SaveSettings();if(Workspace!=null)Workspace.Dispose();}
        public void SmokeOutput(string path){closingSmoke=true;string directory=Path.GetDirectoryName(Path.GetFullPath(path));Directory.CreateDirectory(directory);string checks=SelfTest.ExerciseUI(this);File.WriteAllText(Path.Combine(directory,"ui-check.txt"),checks);Canvas.Fit();if(Document!=null)foreach(var n in Document.Xml.Nodes)if(n.Name.StartsWith("dragdrop_")){Canvas.SelectKey(n.Key,false);break;}SetTheme("classic",false);CapturePreview(path);foreach(string id in ThemeCatalog.Ids){SetTheme(id,false);CapturePreview(Path.Combine(directory,"theme-"+id+".png"));}SetTheme("soc",false);inspectorTabs.SelectedIndex=1;CapturePreview(Path.Combine(directory,"texture-preview.png"));SetTheme("classic",false);Canvas.Export(Path.Combine(directory,"canvas.png"));Close();}
        void CapturePreview(string path){Refresh();Application.DoEvents();using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
        void LoadSettings(){try{if(!File.Exists(settingsPath))return;var x=new XmlDocument();x.XmlResolver=null;x.Load(settingsPath);ReadView(x.DocumentElement);}catch(Exception){}}
        void SaveSettings(){try{Directory.CreateDirectory(Path.GetDirectoryName(settingsPath));var x=new XmlDocument();var root=x.CreateElement("view");x.AppendChild(root);WriteView(root);x.Save(settingsPath);}catch(Exception){}}
        void WriteView(XmlElement e){SaveThemeSettings(e);e.SetAttribute("grid_x",Canvas.Options.GridX.ToString());e.SetAttribute("grid_y",Canvas.Options.GridY.ToString());e.SetAttribute("major",Canvas.Options.Major.ToString());e.SetAttribute("grid_color",Canvas.Options.GridColor.ToArgb().ToString());e.SetAttribute("background_color",Canvas.Options.BackgroundColor.ToArgb().ToString());foreach(var v in toggles)e.SetAttribute(v.Key,v.Value.Checked?"1":"0");}
        void ReadView(XmlElement e){LoadThemeSettings(e);int v;if(int.TryParse(e.GetAttribute("grid_x"),out v)&&v>=1&&v<=1024)Canvas.Options.GridX=v;if(int.TryParse(e.GetAttribute("grid_y"),out v)&&v>=1&&v<=1024)Canvas.Options.GridY=v;if(int.TryParse(e.GetAttribute("major"),out v)&&v>=1&&v<=64)Canvas.Options.Major=v;if(int.TryParse(e.GetAttribute("grid_color"),out v))Canvas.Options.GridColor=Color.FromArgb(v);if(int.TryParse(e.GetAttribute("background_color"),out v))Canvas.Options.BackgroundColor=Color.FromArgb(v);gridX.Text=Canvas.Options.GridX.ToString();gridY.Text=Canvas.Options.GridY.ToString();foreach(var t in toggles)if(e.HasAttribute(t.Key))t.Value.Checked=e.GetAttribute(t.Key)=="1";}
        string Relative(string path){return path.StartsWith(Workspace.Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)?path.Substring(Workspace.Root.Length+1):path;}
        void SaveProject(){if(Workspace==null)return;using(var dialog=new SaveFileDialog{Filter="Настройки проекта|*.halk.xml",FileName="ui_project.halk.xml",InitialDirectory=Workspace.Root})if(dialog.ShowDialog(this)==DialogResult.OK){var x=new XmlDocument();var r=x.CreateElement("ui_editor_project");x.AppendChild(r);r.SetAttribute("root",Workspace.Root);r.SetAttribute("texture_directory",Workspace.TextureDirectory??"");r.SetAttribute("active",Document==null?"":Relative(Document.FilePath));r.SetAttribute("background",Canvas.Options.ManualBackground??"");WriteView(r);foreach(var d in Workspace.Documents.Values){if(d.Hidden.Count==0&&d.Locked.Count==0&&d.PreviewParents.Count==0&&d.EngineParents)continue;var doc=x.CreateElement("document");doc.SetAttribute("file",Relative(d.FilePath));doc.SetAttribute("engine_parents",d.EngineParents?"1":"0");r.AppendChild(doc);foreach(var n in d.Xml.Nodes){if(!d.Hidden.Contains(n.Key)&&!d.Locked.Contains(n.Key)&&!d.PreviewParents.ContainsKey(n.Key))continue;var el=x.CreateElement("node");el.SetAttribute("key",n.Key);if(d.Hidden.Contains(n.Key))el.SetAttribute("hidden","1");if(d.Locked.Contains(n.Key))el.SetAttribute("locked","1");string parent;if(d.PreviewParents.TryGetValue(n.Key,out parent))el.SetAttribute("parent",parent);doc.AppendChild(el);}}x.Save(dialog.FileName);status.Text="Настройки проекта сохранены.";}}
        void LoadProject(){using(var dialog=new OpenFileDialog{Filter="Настройки проекта|*.halk.xml"})if(dialog.ShowDialog(this)==DialogResult.OK){var x=new XmlDocument();x.XmlResolver=null;x.Load(dialog.FileName);var r=x.DocumentElement;if(r.Name!="ui_editor_project")throw new FormatException("Это не файл настроек редактора.");string root=r.GetAttribute("root");if(!Directory.Exists(root))root=Path.GetDirectoryName(dialog.FileName);if(!OpenWorkspace(root,null))return;if(Workspace==null||!string.Equals(Workspace.Root,root,StringComparison.OrdinalIgnoreCase))return;Workspace.TextureDirectory=r.GetAttribute("texture_directory");Canvas.Options.ManualBackground=r.GetAttribute("background");ReadView(r);foreach(XmlElement el in r.SelectNodes("document")){string path=Path.Combine(root,el.GetAttribute("file"));if(!File.Exists(path))continue;var d=Workspace.Open(path);d.EngineParents=el.GetAttribute("engine_parents")!="0";d.Hidden.Clear();d.Locked.Clear();d.PreviewParents.Clear();foreach(XmlElement n in el.SelectNodes("node")){string key=n.GetAttribute("key");if(d.Node(key)==null)continue;if(n.GetAttribute("hidden")=="1")d.Hidden.Add(key);if(n.GetAttribute("locked")=="1")d.Locked.Add(key);if(n.HasAttribute("parent"))d.PreviewParents[key]=n.GetAttribute("parent");}}Workspace.Reindex();string active=r.GetAttribute("active");if(active!=""&&File.Exists(Path.Combine(root,active)))OpenDocument(Path.Combine(root,active));else RefreshDocument(true);}}
    }
