    static class Prompt {
        public static string Ask(IWin32Window owner,string title,string label,string value){using(var f=new Form{Text=title,Width=450,Height=175,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MinimizeBox=false,MaximizeBox=false,Font=new Font("Segoe UI",9)}){var l=new Label{Left=14,Top=13,Width=405,Text=label};var t=new TextBox{Left=14,Top=39,Width=405,Text=value};var ok=new Button{Left=240,Top=78,Width=85,Text="Применить",DialogResult=DialogResult.OK};var cancel=new Button{Left=334,Top=78,Width=85,Text="Отмена",DialogResult=DialogResult.Cancel};f.Controls.AddRange(new Control[]{l,t,ok,cancel});f.AcceptButton=ok;f.CancelButton=cancel;var editor=owner as MainForm;if(editor!=null)ThemeCatalog.Apply(f,editor.ActivePalette);return f.ShowDialog(owner)==DialogResult.OK?t.Text:null;}}
    }
